#include "mechanics.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
using namespace compose;
void require(bool yes,const std::string&why){if(!yes){std::cerr<<"FAIL "<<why<<"\n";std::exit(1);}}
int main(){std::cout<<std::setprecision(12);Config c;c.iterations=0;c.schedule="joint";c.work="dg_average";
    for(const std::string name:{"scalar_release","radial_orbit","elastic_mixed","chain_mixed"}){auto ca=make_case(name);auto s=ca.initial;double en=energy(ca.model,s),scale=std::max(1.0,en-minimum_energy(ca.model));c.family="force_momentum";double maxde=0,maximp=0;for(int i=0;i<100;++i){auto r=mechanics_step(ca.model,s,.01,c,scale);require(r.valid,name+" DG valid "+r.reason);maxde=std::max(maxde,std::abs(energy(ca.model,r.state)-en));maximp=std::max(maximp,r.impulse);s=r.state;}std::cout<<name<<" DG energy "<<maxde<<" impulse "<<maximp<<"\n";require(maxde<2e-7,name+" DG energy");require(maximp<1e-7,name+" DG impulse");}
    {auto ca=make_case("rod_kick");State s=ca.initial;c.family="rattle";double mc=0,mt=0;for(int i=0;i<200;++i){auto r=mechanics_step(ca.model,s,.01,c,10);require(r.valid,"RATTLE valid");s=r.state;mc=std::max(mc,std::abs(s.x.norm()-1));mt=std::max(mt,std::abs(s.x.dot(s.v)));}std::cout<<"RATTLE length "<<mc<<" tangent "<<mt<<"\n";require(mc<2e-9,"RATTLE position");require(mt<2e-9,"RATTLE tangency");}
    {auto ca=make_case("rod_kick");State s=ca.initial;c.family="force_momentum";double en=energy(ca.model,s),mc=0,me=0,mt=0;for(int i=0;i<100;++i){auto r=mechanics_step(ca.model,s,.01,c,10);require(r.valid,"rod DG valid");s=r.state;mc=std::max(mc,std::abs(s.x.norm()-1));me=std::max(me,std::abs(energy(ca.model,s)-en));mt=std::max(mt,std::abs(s.x.dot(s.v)));}std::cout<<"rod DG length "<<mc<<" energy "<<me<<" endpoint tangent "<<mt<<"\n";require(mc<1e-8&&me<2e-7,"rod DG geometry and energy");require(mt>1e-6,"midpoint DG is distinct from endpoint-tangent RATTLE");}
    {auto ca=make_case("scalar_release");c.family="xpbd";c.curvature="full";auto r=mechanics_step(ca.model,ca.initial,.02,c,5);double exact=(ca.initial.x[0]+.02*ca.initial.v[0]+.02*.02*100)/(1+.02*.02*100);std::cout<<"XPBD scalar error "<<std::abs(r.state.x[0]-exact)<<"\n";require(std::abs(r.state.x[0]-exact)<1e-10,"XPBD scalar implicit Euler");}
    {auto ca=make_case("scalar_mixed");c.family="force_momentum";State truth=reference_step(ca.model,ca.initial,.2,10000);auto integrate=[&](double h){State s=ca.initial;for(int i=0;i<int(std::round(.2/h));++i)s=mechanics_step(ca.model,s,h,c,5).state;return (s.x-truth.x).norm()+(s.v-truth.v).norm();};double a=integrate(.02),b=integrate(.01);std::cout<<"midpoint scalar convergence ratio "<<a/b<<"\n";require(a/b>3.5&&a/b<4.5,"second order DG scalar");}
    {auto ca=make_case("scalar_mixed");c.family="fepr_projection";c.curvature="drop";auto r=mechanics_step(ca.model,ca.initial,.02,c,5);std::cout<<"FEPR-style energy "<<r.balance<<" rx "<<r.rx<<"\n";require(r.valid&&r.balance<1e-8,"FEPR-style energy projection");}
    {auto ca=make_case("rod_kick");c.family="fepr_projection";c.tangency=true;auto r=mechanics_step(ca.model,ca.initial,.01,c,10);std::cout<<"FEPR-style constrained energy "<<r.balance<<" length "<<std::abs(r.state.x.norm()-1)<<" tangent "<<std::abs(r.state.x.dot(r.state.v))<<"\n";require(r.valid&&r.balance<1e-8&&std::abs(r.state.x.norm()-1)<1e-8&&std::abs(r.state.x.dot(r.state.v))<1e-8,"FEPR-style constrained projection");}
    {auto ca=make_case("chain_mixed");V mass=masses(ca.model),a=V::Zero(4),b=V::Zero(4);a<<.1,-.3,.2,.1;b<<-.2,.4,.3,-.2;V after=ca.initial.v+mass.cwiseInverse().cwiseProduct(a+b);auto audit=mechanical_detail::audit_impulses(ca.model,ca.initial.v,after,{a,b});std::cout<<"impulse audit common "<<audit.common_defect<<" sequential "<<audit.sequential_defect<<" allocation gap "<<audit.allocation_gap<<"\n";require(audit.common_defect<1e-12&&audit.sequential_defect<1e-12&&audit.closure<1e-12,"impulse audit telescope");require(audit.allocation_gap>1e-3,"impulse allocations distinct");}
    {auto ca=make_case("scalar_mixed");c.family="fepr_projection";c.tangency=false;c.curvature="exact";V positions(3);int k=0;for(double beta:{.1,1.,10.}){c.beta=beta;auto r=mechanics_step(ca.model,ca.initial,.02,c,5);require(r.valid&&r.balance<1e-8,"FEPR beta energy");positions[k++]=r.state.x[0];}std::cout<<"FEPR beta positions "<<positions.transpose()<<"\n";require(std::abs(positions[0]-positions[2])>1e-5,"FEPR beta changes metric");}
    std::cout<<"PASS mechanics numerical validation\n";
}
